            err.println("error: cannot read " + (file == null ? "-" : file));
            err.flush();
            System.exit(2);
            return;
        }

        StringBuilder sb = new StringBuilder();
        sb.append("total: ").append(total).append('\n');
        sb.append("by level: DEBUG=").append(levelCounts[0])
                .append(" INFO=").append(levelCounts[1])
                .append(" WARN=").append(levelCounts[2])
                .append(" ERROR=").append(levelCounts[3])
                .append('\n');
        sb.append("first: ").append(first == null ? "n/a" : first).append('\n');
        sb.append("last: ").append(last == null ? "n/a" : last).append('\n');
        sb.append("top errors:\n");

        List<Group> sorted = new ArrayList<>(groups.values());
        sorted.sort(Comparator.<Group>comparingLong(g -> -g.count).thenComparing(g -> g.display));

        int limit = Math.min(top, sorted.size());
        for (int idx = 0; idx < limit; idx++) {
            Group g = sorted.get(idx);
            sb.append("  ").append(g.count).append(' ').append(g.display).append('\n');
        }

        out.print(sb);
        out.flush();
        System.exit(0);
    }

    private static int levelIndex(String level) {
        for (int i = 0; i < LEVELS.length; i++) {
            if (LEVELS[i].equals(level)) {
                return i;
            }
        }
        return -1;
    }

    private static boolean isValidLevel(String level) {
        return levelIndex(level) >= 0;
    }

    private static boolean isValidTimestamp(String s) {
        if (!TIMESTAMP_PATTERN.matcher(s).matches()) {
            return false;
        }
        int year = Integer.parseInt(s.substring(0, 4));
        int month = Integer.parseInt(s.substring(5, 7));
        int day = Integer.parseInt(s.substring(8, 10));
        int hour = Integer.parseInt(s.substring(11, 13));
        int minute = Integer.parseInt(s.substring(14, 16));
        int second = Integer.parseInt(s.substring(17, 19));
        if (month < 1 || month > 12) return false;
        if (day < 1 || day > 31) return false;
        if (hour > 23) return false;
        if (minute > 59) return false;
        if (second > 59) return false;
        return true;
    }

    private static ParsedLine parseLine(String line) {
        int firstSpace = line.indexOf(' ');
        if (firstSpace < 0) {
            return null;
        }
        int secondSpace = line.indexOf(' ', firstSpace + 1);
        if (secondSpace < 0) {
            return null;
        }
        String timestamp = line.substring(0, firstSpace);
        String level = line.substring(firstSpace + 1, secondSpace);
        String message = line.substring(secondSpace + 1);

        if (!isValidTimestamp(timestamp)) {
            return null;
        }
        if (!isValidLevel(level)) {
            return null;
        }

        return new ParsedLine(timestamp, level, message);
    }

    private static String normalize(String message) {
        String s = message;
        s = UUID_PATTERN.matcher(s).replaceAll("<uuid>");
        s = HEX_PATTERN.matcher(s).replaceAll("<hex>");
        s = DIGIT_PATTERN.matcher(s).replaceAll("<num>");
        return s;
    }

    private static final class ParsedLine {
        final String timestamp;
        final String level;
        final String message;

        ParsedLine(String timestamp, String level, String message) {
            this.timestamp = timestamp;
            this.level = level;
            this.message = message;
        }
    }

    private static final class Group {
        final String display;
        long count;

        Group(String display) {
            this.display = display;
            this.count = 0;
        }
    }
